{

"kind": "propose",
"summary": "The app's CPU limit is too low, causing throttling despite increased limits from the rollout. Raise the CPU limit to 450m.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Current CPU limit of 300m is insufficient, as usage is 280m (93% of limit) with 57% throttling.",
    "supporting": ["ev-container_cpu"],
    "contradicting": [],
    "missing": ["container_cpu_usage_trend", "node_cpu_capacity"],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "The new version (rev 2) uses more CPU than rev 1, despite higher limits.",
    "supporting": ["ev-rollout_history", "ev-container_cpu"],
    "contradicting": ["throttling_came_with_rollout"],
    "missing": ["cpu_usage_comparison_rev1_rev2"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "cpu": "450m"
        }
      }
    }
  },
  "expected_effect": "Raises CPU limit to 450m, reducing throttling from 57% to below 50%.",
  "rationale": "Current limit of 300m is insufficient for 280m usage (93% of limit). Increasing to 450m (1.5x current) addresses the throttling without affecting memory or other resources.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_changed_the_app"]
}
}
